1	import { createContext, useContext, type ReactNode } from "react";
2	import { useCartState } from "@/lib/use-cart-state";
3	import type { CartState, CartActions } from "@/lib/types";
4	
5	type CartContextValue = CartState & CartActions;
6	
7	const CartContext = createContext<CartContextValue | null>(null);
8	
9	export function CartProvider({ children }: { children: ReactNode }) {
10	  const cart = useCartState();
11	  return <CartContext.Provider value={cart}>{children}</CartContext.Provider>;
12	}
13	
14	export function useCart(): CartContextValue {
15	  const ctx = useContext(CartContext);
16	  if (!ctx) throw new Error("useCart must be used within CartProvider");
17	  return ctx;
18	}
