1	import { useEffect, useRef, useState, type RefObject } from "react";
2	import { Button } from "@/components/ui/button";
3	import { useCart } from "@/components/shared/cart-context";
4	import { cn } from "@/lib/utils";
5	
6	interface StickyAddToCartProps {
7	  heroRef: RefObject<HTMLElement | null>;
8	  productName?: string;
9	}
10	
11	export function StickyAddToCart({ heroRef, productName = "Vela Focus Formula" }: StickyAddToCartProps) {
12	  const { totalPrice, openCart } = useCart();
13	  const [visible, setVisible] = useState(false);
14	  const observerRef = useRef<IntersectionObserver | null>(null);
15	
16	  useEffect(() => {
17	    const el = heroRef.current;
18	    if (!el || typeof IntersectionObserver === "undefined") return;
19	    observerRef.current = new IntersectionObserver(
20	      ([entry]) => {
21	        if (!entry) return;
22	        setVisible(!entry.isIntersecting);
23	      },
24	      { threshold: 0, rootMargin: "-80px 0px 0px 0px" },
25	    );
26	    observerRef.current.observe(el);
27	    return () => observerRef.current?.disconnect();
28	  }, [heroRef]);
29	
30	  return (
31	    <div
32	      className={cn(
33	        "fixed inset-x-0 bottom-0 z-40 border-t border-cream-300 bg-cream-50/95 px-4 py-3 backdrop-blur-md md:hidden",
34	        "transition-[opacity,transform] duration-[var(--duration-base)] ease-[var(--ease-out)]",
35	        visible ? "translate-y-0 opacity-100" : "pointer-events-none translate-y-full opacity-0",
36	      )}
37	      aria-hidden={!visible}
38	    >
39	      <div className="flex items-center justify-between gap-3">
40	        <div className="flex flex-col">
41	          <span className="text-sm font-semibold text-forest-950">{productName}</span>
42	          <span className="font-mono text-xs text-ink-600 tabular-nums">
43	            ${totalPrice.toFixed(2)}
44	          </span>
45	        </div>
46	        <Button onClick={openCart} className="bg-forest-800 text-cream-50 hover:bg-forest-900">
47	          Add to cart
48	        </Button>
49	      </div>
50	    </div>
51	  );
52	}
