7	const OPTIONS: ReadonlyArray<{ size: BundleSize; label: string; popular?: boolean }> = [
8	  { size: 1, label: "1 Bottle" },
9	  { size: 2, label: "2 Bottles", popular: true },
10	  { size: 3, label: "3 Bottles" },
11	];
