13	export function BundleSelector() {
14	  const { bundle, setBundle, purchaseType } = useCart();
15	  const base =
16	    purchaseType === "subscribe"
17	      ? VELA_PRODUCT.priceSubscribe
18	      : VELA_PRODUCT.priceOnetime;
19	
20	  return (
21	    <div className="space-y-2">
22	      <p className="font-mono text-xs uppercase tracking-wider text-ink-500">
23	        Choose your supply
24	      </p>
25	      <div className="grid grid-cols-3 gap-2">
26	        {OPTIONS.map((opt) => {
27	          const perBottle = (base * VELA_PRODUCT.bundleMultipliers[opt.size]) / opt.size;
28	          const savings = VELA_PRODUCT.bundleSavings[opt.size];
29	          const active = bundle === opt.size;
30	          return (
31	            <button
32	              key={opt.size}
33	              type="button"
34	              onClick={() => setBundle(opt.size)}
35	              className={cn(
36	                "relative flex flex-col items-start gap-1 rounded-lg border-2 p-3 text-left transition-[border-color,background-color,transform] duration-200 ease-[var(--ease-out)]",
37	                active
38	                  ? "border-forest-800 bg-cream-100 -translate-y-0.5"
39	                  : "border-cream-300 bg-cream-50 hover:border-forest-400",
40	              )}
41	              aria-pressed={active}
42	            >
43	              {opt.popular && (
44	                <Badge
45	                  variant="secondary"
46	                  className="absolute -top-2 right-2 bg-amber-500 text-forest-950 hover:bg-amber-500"
47	                >
48	                  Most popular
49	                </Badge>
50	              )}
51	              <span className="text-sm font-semibold text-forest-950">{opt.label}</span>
52	              <span className="font-mono text-xs text-ink-600">
53	                ${perBottle.toFixed(2)}/bottle
54	              </span>
55	              {savings > 0 ? (
56	                <span className="font-mono text-xs text-forest-700">
57	                  Save {savings}%
58	                </span>
59	              ) : (
60	                <span className="font-mono text-xs text-ink-400">—</span>
61	              )}
62	            </button>
63	          );
64	        })}
65	      </div>
66	    </div>
67	  );
68	}
